snowflake.role_hierarchy_sql:
-- Create role hierarchy
CREATE ROLE HELIX_BRONZE_LOADER;
CREATE ROLE HELIX_SILVER_ENGINEER;
CREATE ROLE HELIX_GOLD_ENGINEER;
CREATE ROLE HELIX_ANALYST_STANDARD;
CREATE ROLE HELIX_ANALYST_CONFIDENTIAL;
CREATE ROLE HELIX_ANALYST_CONFIDENTIAL_UNSCOPED;
CREATE ROLE HELIX_ANALYST_RESTRICTED;
CREATE ROLE HELIX_ANALYST_RESTRICTED_FINAID;
CREATE ROLE HELIX_ANALYST_RESTRICTED_HR;
CREATE ROLE HELIX_STEWARD_ENROLLMENT;
CREATE ROLE HELIX_STEWARD_HR;
CREATE ROLE HELIX_STEWARD_FINANCE;
CREATE ROLE HELIX_STEWARD_ADVANCEMENT;
CREATE ROLE HELIX_STEWARD_ACADEMIC;
CREATE ROLE HELIX_RESEARCH;
CREATE ROLE HELIX_ADMIN;

-- Role inheritance (least to most privileged)
GRANT ROLE HELIX_ANALYST_STANDARD TO ROLE HELIX_ANALYST_CONFIDENTIAL;
GRANT ROLE HELIX_ANALYST_CONFIDENTIAL TO ROLE HELIX_ANALYST_CONFIDENTIAL_UNSCOPED;
GRANT ROLE HELIX_ANALYST_CONFIDENTIAL TO ROLE HELIX_ANALYST_RESTRICTED;

-- Schema grants
GRANT USAGE ON SCHEMA bronze TO ROLE HELIX_BRONZE_LOADER;
GRANT INSERT, CREATE TABLE ON SCHEMA bronze TO ROLE HELIX_BRONZE_LOADER;

GRANT USAGE ON SCHEMA bronze TO ROLE HELIX_SILVER_ENGINEER;
GRANT SELECT ON ALL TABLES IN SCHEMA bronze TO ROLE HELIX_SILVER_ENGINEER;
GRANT USAGE, CREATE TABLE, INSERT, UPDATE ON SCHEMA silver TO ROLE HELIX_SILVER_ENGINEER;

GRANT USAGE ON SCHEMA silver TO ROLE HELIX_GOLD_ENGINEER;
GRANT SELECT ON ALL TABLES IN SCHEMA silver TO ROLE HELIX_GOLD_ENGINEER;
GRANT USAGE, CREATE TABLE, CREATE VIEW, INSERT, UPDATE ON SCHEMA gold TO ROLE HELIX_GOLD_ENGINEER;

GRANT USAGE ON SCHEMA gold TO ROLE HELIX_ANALYST_STANDARD;
GRANT SELECT ON ALL TABLES IN SCHEMA gold TO ROLE HELIX_ANALYST_STANDARD;
-- Note: Masking policies and RLS automatically apply to gold tables

-- Admin grants (no data access)
GRANT MANAGE GRANTS ON ACCOUNT TO ROLE HELIX_ADMIN;
GRANT CREATE ROLE ON ACCOUNT TO ROLE HELIX_ADMIN;
GRANT APPLY MASKING POLICY ON ACCOUNT TO ROLE HELIX_ADMIN;
GRANT APPLY ROW ACCESS POLICY ON ACCOUNT TO ROLE HELIX_ADMIN;

databricks_unity_catalog.setup_sql:
-- Create groups (Unity Catalog uses groups, not roles)
CREATE GROUP helix_bronze_loader;
CREATE GROUP helix_silver_engineer;
CREATE GROUP helix_gold_engineer;
CREATE GROUP helix_analyst_standard;
CREATE GROUP helix_analyst_confidential;
CREATE GROUP helix_analyst_restricted;
CREATE GROUP helix_steward;
CREATE GROUP helix_research;
CREATE GROUP helix_admin;

-- Schema grants
GRANT USE SCHEMA ON SCHEMA helix_catalog.bronze TO helix_bronze_loader;
GRANT CREATE TABLE ON SCHEMA helix_catalog.bronze TO helix_bronze_loader;

GRANT USE SCHEMA, SELECT ON SCHEMA helix_catalog.bronze TO helix_silver_engineer;
GRANT USE SCHEMA, SELECT, CREATE TABLE, MODIFY ON SCHEMA helix_catalog.silver TO helix_silver_engineer;

GRANT USE SCHEMA, SELECT ON SCHEMA helix_catalog.silver TO helix_gold_engineer;
GRANT USE SCHEMA, SELECT, CREATE TABLE, MODIFY ON SCHEMA helix_catalog.gold TO helix_gold_engineer;

GRANT USE SCHEMA, SELECT ON SCHEMA helix_catalog.gold TO helix_analyst_standard;

-- Column masks (Unity Catalog 2024+)
ALTER TABLE helix_catalog.silver.aid_application
  ALTER COLUMN sai
  SET MASK helix_mask_restricted;

-- Row filters
ALTER TABLE helix_catalog.gold.dim_student
  SET ROW FILTER helix_rls_ferpa_directory ON (student_ref);

aws_lake_formation.terraform_example:
resource "aws_lakeformation_permissions" "analyst_standard" {
  principal   = aws_iam_role.helix_analyst_standard.arn
  permissions = ["SELECT"]

  lf_tag_policy {
    resource_type = "TABLE"
    expression {
      key    = "helix_classification"
      values = ["public", "internal"]
    }
  }
}

redshift.setup_sql:
-- Create groups
CREATE GROUP helix_bronze_loader;
CREATE GROUP helix_silver_engineer;
CREATE GROUP helix_gold_engineer;
CREATE GROUP helix_analyst_standard;
CREATE GROUP helix_analyst_confidential;
CREATE GROUP helix_analyst_restricted;
CREATE GROUP helix_steward;
CREATE GROUP helix_research;

-- Schema grants
GRANT USAGE ON SCHEMA bronze TO GROUP helix_bronze_loader;
GRANT INSERT ON ALL TABLES IN SCHEMA bronze TO GROUP helix_bronze_loader;

GRANT USAGE ON SCHEMA bronze TO GROUP helix_silver_engineer;
GRANT SELECT ON ALL TABLES IN SCHEMA bronze TO GROUP helix_silver_engineer;
GRANT USAGE, CREATE ON SCHEMA silver TO GROUP helix_silver_engineer;

-- Column-level GRANT for restricted columns
-- Redshift supports column-level GRANT natively:
GRANT SELECT (helix_id, student_ref, academic_year, aid_application_status, dependency_status)
  ON silver.aid_application TO GROUP helix_gold_engineer;
-- Note: sai, efc_legacy, nslds_match_flags columns NOT granted → access denied

GRANT SELECT (helix_id, student_ref, academic_year, aid_application_status, dependency_status, sai, efc_legacy, nslds_match_flags)
  ON silver.aid_application TO GROUP helix_analyst_restricted;

-- RLS via views (Redshift lacks native RLS policies)
CREATE VIEW gold.dim_student_ferpa_safe AS
SELECT s.*
FROM gold.dim_student s
WHERE NOT EXISTS (
  SELECT 1 FROM silver.ferpa_restriction fr
  WHERE fr.student_ref = s.student_ref
    AND fr.is_active = TRUE
    AND fr.restrict_directory = TRUE
)
OR pg_has_role(CURRENT_USER, 'helix_analyst_confidential', 'member');

GRANT SELECT ON gold.dim_student_ferpa_safe TO GROUP helix_analyst_standard;
